const TRASH_RETENTION_MS=30*24*60*60*1000;
async function cleanupExpiredTrash(key=vaultKey,generation=vaultGeneration){const valid=()=>vaultSessionValid(key,generation);if(!valid())return false;const cutoff=Date.now()-TRASH_RETENTION_MS,expired=trashRows().filter(x=>x.deletedAt<=cutoff);let changed=false,failed=false;for(const x of expired){try{const deleted=await permanentlyDelete(x,key,generation);if(!valid())return false;if(deleted)changed=true}catch{if(!valid())return false;failed=true}}if(!valid())return false;if(changed)markVaultUpdated();if(failed)toast('部分过期资料清理失败，已保留并将在下次解锁时重试');return true}
let trashDeleteTarget=null;
function trashParentNote(x){return resolveTrashParentNote(x,items)}
function linkedTrashAttachments(x){return resolveLinkedTrashAttachments(x,attachments,items)}
async function permanentlyDelete(x,key=vaultKey,generation=vaultGeneration){const valid=()=>vaultSessionValid(key,generation);if(!valid()||(x.type==='attachment'?!attachments.includes(x):!items.includes(x)))return false;if(x.type==='attachment'){await api('/api/attachments/'+x.id,{method:'DELETE',headers:{'if-match':String(x.revision)}});if(!valid())return false;attachments=attachments.filter(v=>v!==x);revokeUrls()}else{const linked=linkedTrashAttachments(x),detached=[];try{for(const file of linked){const candidate={...file};delete candidate.trashOwnerId;await putGroupedValue(candidate);if(!valid())return false;detached.push(file)}await api('/api/entries/'+x.id,{method:'DELETE',headers:{'if-match':String(x.revision)}});if(!valid())return false}catch(err){if(!valid())return false;if(err?.code==='conflict')pendingExternalUpdate=true;let compensationFailed=false;for(const file of detached.reverse())try{await putGroupedValue(file);if(!valid())return false}catch{if(!valid())return false;compensationFailed=true}if(compensationFailed)try{if(await load())render(false)}catch{}if(!valid())return false;throw Error(compensationFailed?'彻底删除失败且附件回滚未完成，已重新同步，请重试':err.message)}items=items.filter(v=>v!==x);for(const file of linked)delete file.trashOwnerId;let attachmentFailure=false;for(const file of linked)try{if(!await permanentlyDelete(file,key,generation)&&!valid())return false}catch{if(!valid())return false;attachmentFailure=true}if(attachmentFailure){const err=Error('关联附件未全部删除，已保留为独立回收站项目，可单独重试');err.partial=true;throw err}}if(!valid())return false;recents=recents.filter(r=>!(r.type===x.type&&r.id===x.id));return true}
